 svg+='<text x="'+(w/2)+'" y="'+(h-10)+'" text-anchor="middle" font-size="12" fill="#3b5c75">OpenAI gpt-5.4 · 초</text><text x="'+l+'" y="20" font-size="11" fill="#3b5c75">Local qwen3.8:27b · 초</text>';
