def serialize(data):
    return json.dumps(data, ensure_ascii=False, separators=(',', ':')).replace('</', r'<\/')


def render_page(filename, title, subtitle, body, script, active):
    data = copy.deepcopy(DATA)
    if active == 'cases':
        data['images'] = {}
        for doc in data['documents']:
            image_path = ROOT / 'docs/ocr_eval_2026-10-09/img' / (doc['id'] + '.jpg')
            assert image_path.exists()
            data['images'][doc['id']] = 'data:image/jpeg;base64,' + base64.b64encode(image_path.read_bytes()).decode()
    else:
        for doc in data['documents']:
            doc.pop('rows', None)
            doc.pop('extras', None)
    nav = [('index.html', 'summary', '전체 성능'), ('cases.html', 'cases', '사진 ↔ OCR'), ('test_types.html', 'types', '검사유형별'), ('models.html', 'models', '모델 비교')]
    links = ''.join(f'<a href="{f}"'+(' aria-current="page"' if key == active else '')+'>'+label+'</a>' for f, key, label in nav)
